  return `<!-- BEGIN -->
<!-- 最后更新时间 ${new Date()} -->
${
    words.map((x, i) => `${i+1}. [${x.title}](https://sspai.com/post/${x.id})`)
      .join("\n")
  }
<!-- END -->`;
}

function createArchive(words, date) {
  return `# ${date}\n
共 ${words.length} 条\n
${createList(words)}
`;
}

