printf("Quantos números você deseja incluir na sequência de Fibonacci: ");
scanf("%lu", &n);

//Gerando a sequência de Fibonacci
for(i=0; i<n; i++)
printf("%lu, ",fibonacci(i));
printf("...\n");

//Finalizando a aplicação
return 0;
          }

