      if (error) {
        throw error;
      }

      const jsTemplate = `export default "${result.symbol.sprite.contents.toString().replace(/\"/g, "'")}";`
        .trim()
        .concat('\n');

      fs.writeFileSync(item.output, jsTemplate);
    });
  });
});

